WITH kept_keys AS (SELECT id FROM transactions INTERSECT ALL SELECT id FROM transactions WHERE is_flagged = TRUE), reconciled AS (SELECT s.* FROM transactions s INNER JOIN kept_keys k ON s.id = k.id) SELECT CASE WHEN amount >= 3000 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, MAX(amount) FILTER (WHERE merchant = 'Shell') AS shell_max_amount, COUNT(CASE WHEN merchant = 'Amazon' THEN 1 END) AS amazon_count, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, COUNT(CASE WHEN txn_type = 'DEBIT' THEN 1 END) AS debit_count FROM reconciled GROUP BY CASE WHEN amount >= 3000 THEN 'LARGE' ELSE 'SMALL' END ORDER BY num_txn_types DESC
